Web Frontend.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Web Frontend container

Container_Boundary(web_frontend_boundary, "Web Frontend") {
    Component(web_frontend_bff_static_assets, "Web Frontend (BFF & Static Assets)", "Kubernetes-backed SSR/BFF with CDN caching", "Manages server-side rendering, BFF logic, and static assets delivery ensuring <1s P95 EMR rendering and WCAG 2.1 AA compliance.")
}

System_Ext(api_gateway, "API Gateway", "Handles incoming traffic, OAuth2/OIDC, and ABAC enforcement.")

Rel(web_frontend_bff_static_assets, api_gateway, "Routes requests", "HTTPS/TLS")

@enduml

Patient Portal / Mobile App.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(patient_portal_mobile_app, "Patient Portal / Mobile App") {
    Component(Self_Registration_Component, "Self-Registration Component", "React Native / Flutter", "Handles patient onboarding and profile creation.")
    Component(Appointment_Booking_Component, "Appointment Booking Component", "React Native / Flutter", "Manages scheduling and viewing of clinic appointments.")
    Component(EMR_Access_Component, "EMR Access Component", "React Native / Flutter with local SQLite (AES-256)", "Provides secure access to patient medical records and mobile data storage.")
}

System(API_Gateway, "API Gateway", "Entry point handling OAuth2/OIDC, ABAC, TLS termination, and request routing.")

Rel(Self_Registration_Component, API_Gateway, "Sends registration requests", "HTTPS/TLS")
Rel(Appointment_Booking_Component, API_Gateway, "Sends scheduling requests", "HTTPS/TLS")
Rel(EMR_Access_Component, API_Gateway, "Retrieves EMR data", "HTTPS/TLS with W3C Trace Context headers")

@enduml

EMR Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the EMR Service container

Container_Boundary(emr_service, "EMR Service") {
    Component(Audit___Compliance_Tracker, "Audit & Compliance Tracker", "Microservice Internal Component", "Tracks audit trails and compliance metrics, writing asynchronous compliance logs to WORM storage.")
    Component(Read_Only_Offline_Cache_Component, "Read-Only Offline Cache Component", "Local Cache Component", "Provides local offline caching to ensure sub-second EMR performance during network interruptions.")
}

Rel(emr_service, Audit___Compliance_Tracker, "Writes asynchronous compliance logs", "Asynchronous")
Rel(emr_service, Read_Only_Offline_Cache_Component, "Retrieves cached patient and clinical data", "Internal")

@enduml

OpenTelemetry sidecars.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the OpenTelemetry sidecars container

Container_Boundary(otel_sidecars, "OpenTelemetry sidecars") {
    Component(OpenTelemetry_Collector, "OpenTelemetry Collector", "OpenTelemetry Collector, C++, Go", "Collects, processes, and exports distributed tracing telemetry and performance metrics without impacting core clinical workflows.")
    Component(mTLS_Handler, "mTLS Handler", "SPIFFE/SPIRE, gRPC", "Handles secure communication using mTLS transport and SPIFFE/SPIRE identities across hybrid boundaries.")
}

Rel(OpenTelemetry_Collector, mTLS_Handler, "Transmits OTLP telemetry securely over mTLS", "gRPC / mTLS")

@enduml
